}
function cleanHomepageName(value) {
  let text = String(value || '').replace(/\s+/g, ' ').trim();
  if (!text) return '';
  const tokens = ["singapore", "bishan", "bukit merah", "bukit timah", "downtown core", "geylang", "kallang", "marina east", "marina south", "marine parade", "museum", "newton", "novena", "orchard", "outram", "queenstown", "river valley", "rochor", "singapore river", "southern islands", "straits view", "tanglin", "toa payoh", "bedok", "changi", "changi bay", "pasir ris", "paya lebar", "tampines", "central water catchment", "lim chu kang", "mandai", "sembawang", "simpang", "sungei kadut", "woodlands", "yishun", "ang mo kio", "hougang", "north-eastern islands", "punggol", "seletar", "sengkang", "serangoon", "boon lay", "bukit batok", "bukit panjang", "choa chu kang", "clementi", "jurong east", "jurong west", "pioneer", "tengah", "tuas", "western islands", "western water catchment"];
