function escapeRegExp(value) {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
function normalizeRoot(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  if (!match) return '';
  const hostname = String(match[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  if (!hostname || !hostname.includes('.')) return '';
  return 'https://' + hostname + '/';
}
function canonicalDomain(value) {
  const root = normalizeRoot(value);
  const match = root.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
}
function registrableLabel(hostname) {
  const labels = String(hostname || '').split('.').filter(Boolean);
  if (labels.length >= 3 && labels[labels.length - 1] === 'sg' && ['com','org','net','edu','gov'].includes(labels[labels.length - 2])) return labels[labels.length - 3] || '';
  return labels[labels.length - 2] || labels[0] || '';
}
function splitLabel(label) {
  const raw = String(label || '').toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
  if (!raw) return [];
  return raw.replace(/([0-9])([a-z])/g, '$1-$2').replace(/([a-z])([0-9])/g, '$1-$2').split('-').filter(Boolean);
}
function prettyToken(token) {
  const t = String(token || '');
  if (!t) return '';
  if (/^\d+$/.test(t)) return t;
  if (t.length <= 3 && /^[a-z]+$/i.test(t)) return t.toUpperCase();
  return t.charAt(0).toUpperCase() + t.slice(1);
}
function cleanCompanyNameFromUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const match = raw.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  const hostname = String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  if (!hostname) return '';
  return splitLabel(registrableLabel(hostname)).map(prettyToken).join(' ').replace(/\s+/g, ' ').trim();
}
function cleanHomepageName(value) {
  let text = String(value || '').replace(/\s+/g, ' ').trim();
  if (!text) return '';
  const tokens = ["singapore", "bishan", "bukit merah", "bukit timah", "downtown core", "geylang", "kallang", "marina east", "marina south", "marine parade", "museum", "newton", "novena", "orchard", "outram", "queenstown", "river valley", "rochor", "singapore river", "southern islands", "straits view", "tanglin", "toa payoh", "bedok", "changi", "changi bay", "pasir ris", "paya lebar", "tampines", "central water catchment", "lim chu kang", "mandai", "sembawang", "simpang", "sungei kadut", "woodlands", "yishun", "ang mo kio", "hougang", "north-eastern islands", "punggol", "seletar", "sengkang", "serangoon", "boon lay", "bukit batok", "bukit panjang", "choa chu kang", "clementi", "jurong east", "jurong west", "pioneer", "tengah", "tuas", "western islands", "western water catchment"];
  text = text
    .replace(/\s*[\-|–—]\s*(?:Singapore|Official|Homepage|Home).*$/i, '')
    .replace(/\([^)]*\)/g, ' ')
    .replace(/\b(?:pte\.?\s*ltd\.?|private\s+limited|limited|ltd\.?|llp|inc\.?|corp\.?|corporation|co\.?|sdn\.?\s*bhd\.?)\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const hadLocation = tokens.some((token) => new RegExp('\\b' + escapeRegExp(token) + '\\b', 'i').test(text));
  for (const token of tokens) {
    text = text.replace(new RegExp('\\b' + escapeRegExp(token) + '\\b', 'gi'), ' ');
  }
  text = text.replace(/\s+/g, ' ').trim();
  if (hadLocation && /^\d/.test(text) && /\bclinic\b$/i.test(text)) {
    text = text.replace(/\bclinic\b$/i, '').trim();
  }
  return text;
}
function isHtml(headers) {
  const entries = Object.entries(headers || {});
  for (const [k, v] of entries) {
    if (String(k).toLowerCase() === 'content-type' && /text\/html|application\/xhtml\+xml/i.test(String(v || ''))) return true;
  }
  return false;
}
